-- 印尼走货明细系统 — PostgreSQL 16 Schema (schema: indo_shipping)
-- 由 db/rebuild_schema.sql (SQL Server T-SQL, 已废弃) 翻译而来；
-- 表名/列名以 src/IndoShipping.Infrastructure/Persistence/AppDbContext.cs 的 EF 映射为准
-- ("Users" 及其列为 PascalCase 带双引号，其余表/列全小写)。
--
-- 运行方式（幂等，可重复执行）:
--   docker cp postgres_schema.sql rr-portal-db-1:/tmp/
--   docker exec rr-portal-db-1 psql -U rrportal -d rrportal -v ON_ERROR_STOP=1 -f /tmp/postgres_schema.sql
--
-- 方言转换对照:
--   INT IDENTITY(1,1)                  → INT GENERATED BY DEFAULT AS IDENTITY
--   NVARCHAR(n) / NVARCHAR(MAX)        → VARCHAR(n) / TEXT
--   DATETIME2(0) DEFAULT SYSUTCDATETIME() → TIMESTAMP(0) DEFAULT now()
--   BIT DEFAULT 1/0                    → BOOLEAN DEFAULT true/false
--   ISJSON() CHECK                     → 列类型直接改 JSONB（去掉 CHECK）
--   T-SQL LIKE '[01]...' CHECK         → 正则 ~ '^[01]{9}$'
--   N'...' 前缀 / [key] / GO           → 去掉 / "key" / 删除

CREATE SCHEMA IF NOT EXISTS indo_shipping;
SET search_path TO indo_shipping;

-- ============ 身份与权限 ============
CREATE TABLE IF NOT EXISTS "Users" (
    "Id"              INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Username"        VARCHAR(64)  NOT NULL,
    "PasswordHash"    VARCHAR(255) NOT NULL,
    "DisplayName"     VARCHAR(128) NOT NULL DEFAULT '',
    "Userbqrpower"    CHAR(9)      NOT NULL DEFAULT '000000000',
    "Usereditpower"   CHAR(9)      NOT NULL DEFAULT '000000000',
    "IsActive"        BOOLEAN      NOT NULL DEFAULT true,
    "CreatedAt"       TIMESTAMP(0) NOT NULL DEFAULT now(),
    CONSTRAINT "UQ_Users_Username" UNIQUE ("Username"),
    CONSTRAINT "CK_Users_Userbqrpower_Binary" CHECK ("Userbqrpower" ~ '^[01]{9}$'),
    CONSTRAINT "CK_Users_Usereditpower_Binary" CHECK ("Usereditpower" ~ '^[01]{9}$')
);

-- Bootstrap-only disabled admin; IndoShipping.Bootstrap replaces this hash from the environment.
